# General cohort analysis functions. Inputs, estimands and thresholds are supplied by the caller.
require_namespace <- function(p){if(!requireNamespace(p,quietly=TRUE))stop("Install ",p)}
check_survival <- function(d){stopifnot(all(c("id","time","status") %in% names(d)),!anyDuplicated(d$id));if(anyNA(d[c("id","time","status")])||any(d$time<=0)||!all(d$status %in% 0:2))stop("Require positive observed time and status 0=censored, 1=dementia, 2=death before dementia");d}
sequential_flow <- function(d,rules){remaining<-rep(TRUE,nrow(d));reason<-rep(NA_character_,nrow(d));out<-list();for(nm in names(rules)){hit<-rules[[nm]];if(length(hit)!=nrow(d)||anyNA(hit))stop("Invalid exclusion flag: ",nm);take<-remaining&hit;out[[nm]]<-data.frame(step=nm,entering=sum(remaining),excluded=sum(take),remaining=sum(remaining&!hit));reason[take]<-nm;remaining[take]<-FALSE};list(flow=do.call(rbind,out),membership=data.frame(id=d$id,included=remaining,first_exclusion=reason))}
baseline_compare <- function(d,group,variables){g<-d[[group]];if(anyNA(g)||!all(g %in% 0:1))stop("Comparison group must be 0/1");out<-list();for(v in variables){x<-d[[v]];a<-x[g==1];b<-x[g==0];if(is.numeric(x)){den<-sqrt((var(a,na.rm=TRUE)+var(b,na.rm=TRUE))/2);out[[v]]<-data.frame(variable=v,level="continuous",included=mean(a,na.rm=TRUE),excluded=mean(b,na.rm=TRUE),available_in=sum(!is.na(a)),available_out=sum(!is.na(b)),missing_in=sum(is.na(a)),missing_out=sum(is.na(b)),SMD=(mean(a,na.rm=TRUE)-mean(b,na.rm=TRUE))/den)}else{lev<-sort(unique(as.character(x[!is.na(x)])));out[[v]]<-do.call(rbind,lapply(lev,function(l){pa<-mean(a==l,na.rm=TRUE);pb<-mean(b==l,na.rm=TRUE);den<-sqrt((pa*(1-pa)+pb*(1-pb))/2);data.frame(variable=v,level=l,included=pa,excluded=pb,available_in=sum(!is.na(a)),available_out=sum(!is.na(b)),missing_in=sum(is.na(a)),missing_out=sum(is.na(b)),SMD=if(den>0)(pa-pb)/den else NA_real_)}))}};do.call(rbind,out)}
score_from_indicators <- function(d,columns,center=NULL,scale=NULL){x<-as.matrix(d[,columns,drop=FALSE]);if(anyNA(x)||!all(x %in% 0:1))stop("Supply complete, oriented binary indicators");raw<-rowMeans(x);if(is.null(center))center<-mean(raw);if(is.null(scale))scale<-sd(raw);if(!is.finite(scale)||scale<=0)stop("Invalid score SD");list(raw=raw,z=(raw-center)/scale,center=center,scale=scale)}
make_formula <- function(rhs,event=1L){as.formula(paste0("survival::Surv(time,status==",event,") ~ ",rhs))}
cox_model <- function(d,rhs,event=1L){check_survival(d);survival::coxph(make_formula(rhs,event),data=d,ties="efron",x=TRUE,y=TRUE,model=TRUE,na.action=na.fail)}
cox_table <- function(f){s<-summary(f);data.frame(term=rownames(s$coefficients),HR=s$conf.int[,1],lower=s$conf.int[,3],upper=s$conf.int[,4],P=s$coefficients[,ncol(s$coefficients)],N=f$n,events=f$nevent)}
screen_cox <- function(d,variables,adjust=character()){out<-lapply(variables,function(v){vars<-unique(c("id","time","status",v,adjust));x<-d[complete.cases(d[,vars,drop=FALSE]),];rhs<-paste(c(v,setdiff(adjust,v)),collapse="+");f<-cox_model(x,rhs);r<-cox_table(f);mm<-model.matrix(f);wanted<-colnames(mm)[attr(mm,"assign")==1L];r<-r[r$term %in% wanted,,drop=FALSE];r$indicator<-v;r});z<-do.call(rbind,out);z$FDR_contrast<-p.adjust(z$P,"BH");z}
fine_gray <- function(d,rhs){require_namespace("cmprsk");check_survival(d);mf<-model.frame(as.formula(paste("~",rhs)),d,na.action=na.fail);mm<-model.matrix(~.,mf);mm<-mm[,colnames(mm)!="(Intercept)",drop=FALSE];if(ncol(mm)==0)stop("No covariates");f<-cmprsk::crr(d$time,d$status,cov1=mm,failcode=1,cencode=0);se<-sqrt(diag(f$var));list(fit=f,table=data.frame(term=names(f$coef),sHR=exp(f$coef),lower=exp(f$coef-1.96*se),upper=exp(f$coef+1.96*se),P=2*pnorm(-abs(f$coef/se)),converged=f$converged))}
aj_curve <- function(d,group){check_survival(d);d$endpoint<-factor(d$status,levels=0:2,labels=c("censored","dementia","death"));survival::survfit(as.formula(paste("survival::Surv(time,endpoint)~",group)),data=d,id=id)}
net_risk <- function(f,newdata,horizon){if(horizon>max(f$y[,1]))stop("Horizon beyond observed follow-up");sf<-survival::survfit(f,newdata=newdata);as.numeric(1-summary(sf,times=horizon,extend=FALSE)$surv)}
# Paired cause-specific hazards; no strata in this implementation.
cif_risk <- function(d,rhs,newdata,horizon){if(grepl("strata\\(",rhs))stop("CIF integration requires an unstratified model");fd<-cox_model(d,rhs,1);fm<-cox_model(d,rhs,2);if(horizon>max(d$time))stop("Horizon beyond follow-up");a<-survival::basehaz(fd,centered=FALSE);b<-survival::basehaz(fm,centered=FALSE);tt<-sort(unique(c(a$time[a$time<=horizon],b$time[b$time<=horizon])));step<-function(z){vapply(tt,function(t){k<-which(z$time<=t);if(length(k))z$hazard[max(k)]else 0},numeric(1))};da<-diff(c(0,step(a)));db<-diff(c(0,step(b)));ed<-exp(predict(fd,newdata,type="lp",reference="zero"));em<-exp(predict(fm,newdata,type="lp",reference="zero"));vapply(seq_along(ed),function(i){h1<-da*ed[i];h2<-db*em[i];h<-h1+h2;s<-exp(-c(0,head(cumsum(h),-1)));sum(s*ifelse(h>0,h1/h,0)*(-expm1(-h)))},numeric(1))}
bootstrap_stat <- function(d,stat,B=200L,seed=1L){set.seed(seed);point<-stat(d);draws<-matrix(NA_real_,B,length(point));fail<-character(B);for(i in seq_len(B)){x<-d[sample.int(nrow(d),replace=TRUE),];x$id<-seq_len(nrow(x));z<-tryCatch(stat(x),error=function(e)e);if(inherits(z,"error"))fail[i]<-conditionMessage(z)else draws[i,]<-z};list(point=point,interval=apply(draws,2,quantile,probs=c(.025,.975),na.rm=TRUE),draws=draws,failures=fail)}
incremental_models <- function(d,rhs){fits<-lapply(rhs,function(r)cox_model(d,r));rows<-lapply(seq_along(fits),function(i){f<-fits[[i]];s<-summary(f);data.frame(model=names(rhs)[i],N=f$n,events=f$nevent,C=s$concordance[1],C_SE=s$concordance[2],AIC=AIC(f))});list(fits=fits,table=do.call(rbind,rows))}
compare_nested <- function(full,reduced){if(full$n!=reduced$n||!identical(rownames(full$model),rownames(reduced$model)))stop("Models must use identical records");lr<-2*as.numeric(logLik(full)-logLik(reduced));df<-attr(logLik(full),"df")-attr(logLik(reduced),"df");if(df<=0)stop("Full model must have more parameters");data.frame(LR=lr,DF=df,P=pchisq(lr,df,lower.tail=FALSE),Delta_AIC=AIC(reduced)-AIC(full))}
ph_test <- function(f){z<-survival::cox.zph(f);data.frame(term=rownames(z$table),z$table,row.names=NULL)}
period_cox <- function(d,rhs,cuts){check_survival(d);if(any(cuts<=0)||is.unsorted(cuts,strictly=TRUE))stop("Invalid cutpoints");d$event<-as.integer(d$status==1);Surv<-survival::Surv;x<-survival::survSplit(Surv(time,event)~.,data=d,cut=cuts,episode="period",start="start");lapply(split(x,x$period),function(q)survival::coxph(as.formula(paste("survival::Surv(start,time,event)~",rhs)),q,ties="efron",x=TRUE,na.action=na.fail))}
landmark_cox <- function(d,rhs,lag){x<-d[d$time>lag,];x$time<-x$time-lag;cox_model(x,rhs)}
multiple_impute <- function(d,columns,predictors,m=20L,maxit=20L,seed=1L){require_namespace("mice");check_survival(d);forbidden<-c("id","time","status");if(any(columns %in% forbidden))stop("Never impute ID, follow-up or outcome");v<-unique(c(columns,predictors,"time","status"));x<-d[,v,drop=FALSE];x$event<-as.integer(d$status==1);x$death<-as.integer(d$status==2);x$log_time<-log(d$time);for(ev in c("event","death")){f<-survival::coxph(survival::Surv(time,x[[ev]])~1,data=d);bh<-survival::basehaz(f,centered=FALSE);x[[paste0("hazard_",ev)]]<-vapply(d$time,function(t){ii<-which(bh$time<=t);if(length(ii))bh$hazard[max(ii)]else 0},numeric(1))};meth<-mice::make.method(x);meth[!names(meth)%in%columns]<-"";meth[colSums(is.na(x))==0]<-"";pr<-mice::make.predictorMatrix(x);pr[meth=="",]<-0;imp<-mice::mice(x,m=m,maxit=maxit,method=meth,predictorMatrix=pr,seed=seed,printFlag=FALSE);completed<-lapply(seq_len(m),function(i){z<-d;y<-mice::complete(imp,i);z[,columns]<-y[,columns,drop=FALSE];z});list(mids=imp,completed=completed)}
pool_cox <- function(completed,rhs){require_namespace("mice");fits<-lapply(completed,function(d)cox_model(d,rhs));mice::pool(mice::as.mira(fits))}
selection_ipw <- function(registry,selected,predictors,trim=c(.01,.99)){f<-glm(reformulate(predictors,selected),registry,family=binomial(),na.action=na.fail);p<-predict(f,type="response");if(any(p<=0|p>=1))stop("Nonpositive selection probabilities");keep<-registry[[selected]]==1;w<-mean(keep)/p[keep];limits<-quantile(w,trim);list(id=registry$id[keep],weights=pmin(pmax(w,limits[1]),limits[2]),untrimmed=w,model=f,limits=limits,ESS=sum(w)^2/sum(w^2))}
# Time-varying IPCW: loss_to_followup is an observed flag, not all status==0 censoring.
ipcw_cox <- function(d,rhs,censor_predictors,probability_floor=.01){check_survival(d);if(!"loss_to_followup"%in%names(d)||anyNA(d$loss_to_followup))stop("Require known loss-to-followup flags");if(any(d$loss_to_followup==1 & d$status!=0))stop("A loss cannot simultaneously be an observed event");cf<-survival::coxph(as.formula(paste("survival::Surv(time,loss_to_followup)~",censor_predictors)),d,x=TRUE,na.action=na.fail);bh<-survival::basehaz(cf,centered=FALSE);lp<-exp(predict(cf,type="lp",reference="zero"));tt<-sort(unique(d$time[d$status==1]));rows<-list();for(i in seq_len(nrow(d))){ends<-sort(unique(c(tt[tt<d$time[i]],d$time[i])));q<-d[rep(i,length(ends)),];q$start<-c(0,head(ends,-1));q$stop<-ends;q$event<-as.integer(ends==d$time[i]&d$status[i]==1);h<-vapply(ends,function(t){j<-which(bh$time<t);if(length(j))bh$hazard[max(j)]else 0},numeric(1));q$G<-exp(-h*lp[i]);q$weight<-1/pmax(q$G,probability_floor);rows[[i]]<-q};long<-do.call(rbind,rows);fit<-survival::coxph(as.formula(paste("survival::Surv(start,stop,event)~",rhs)),long,weights=weight,cluster=id,robust=TRUE,x=TRUE,na.action=na.fail);list(fit=fit,censor_model=cf,diagnostics=data.frame(min_G=min(long$G),fraction_floored=mean(long$G<probability_floor),max_weight=max(long$weight)))}

weighted_cox <- function(d,rhs,weights){check_survival(d);if(length(weights)!=nrow(d)||any(!is.finite(weights))||any(weights<=0))stop("Invalid weights or row alignment");d$analysis_weight<-weights;survival::coxph(make_formula(rhs),d,weights=analysis_weight,cluster=id,robust=TRUE,x=TRUE,model=TRUE,na.action=na.fail)}
# Controlled departure for continuous imputed covariates; observed cells never change.
continuous_delta_sensitivity <- function(completed,original,variable,deltas,analysis){if(!is.numeric(original[[variable]]))stop("Continuous covariates only");missing<-is.na(original[[variable]]);lapply(deltas,function(delta){datasets<-lapply(completed,function(d){stopifnot(identical(d$id,original$id));d[missing,variable]<-d[missing,variable]+delta;d});list(delta=delta,result=analysis(datasets))})}
